function buildBlackRose(){const roseGroup=new THREE.Group;const GOLDEN_ANGLE=137.508*(Math.PI/180);const petalCoreMat=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const petalMidMat=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const petalOuterMat=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const stemMat=new THREE.MeshStandardMaterial({color:2449704,emissive:1457944,emissiveIntensity:0.14,roughness:0.85,metalness:0});const thornMat=new THREE.MeshLambertMaterial({color:0});const leafMat=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const sepalMat=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const fallenMat1=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});const fallenMat2=new THREE.MeshLambertMaterial({color:0,side:THREE.DoubleSide});function makePetalGeo(w,h,curl,cup,ruffle,segments){const segsU=segments||14;const segsV=segments||14;const verts=[];const uvs=[];const indices=[];for(let iv=0;iv<=segsV;iv++){const v=iv/segsV;const widthProfile=Math.sin(v*Math.PI*0.85)*(1-v*0.15);const halfW=w*0.5*widthProfile;for(let iu=0;iu<=segsU;iu++){const u=iu/segsU;const uCentered=(u-0.5)*2;let px=uCentered*halfW;let py=h*v;const cupDepth=cup*(1-uCentered*uCentered)*v*v;let pz=-cupDepth;const curlAmount=curl*v*v*v;const cAngle=curlAmount;const newPy=py*Math.cos(cAngle)-pz*Math.sin(cAngle);const newPz=py*Math.sin(cAngle)+pz*Math.cos(cAngle);py=newPy;pz=newPz;const edgeFactor=Math.pow(Math.abs(uCentered),2.5);const ruffleWave=ruffle*edgeFactor*Math.sin(v*Math.PI*3+uCentered*4)*v;pz+=ruffleWave;const veinBump=0.0008*Math.sin(v*Math.PI*6)*(1-Math.abs(uCentered));pz+=veinBump;verts.push(px,py,pz);uvs.push(u,v)}}for(let iv=0;iv<segsV;iv++){for(let iu=0;iu<segsU;iu++){const a=iv*(segsU+1)+iu;const b=a+1;const c=a+segsU+1;const d=c+1;indices.push(a,c,b,b,c,d)}}const geo=new THREE.BufferGeometry;geo.setAttribute("position",new THREE.Float32BufferAttribute(verts,3));geo.setAttribute("uv",new THREE.Float32BufferAttribute(uvs,2));geo.setIndex(indices);geo.computeVertexNormals();return geo}const bloom=new THREE.Group;const totalPetals=45;for(let i=0;i<totalPetals;i++){const t=i/totalPetals;const angle=i*GOLDEN_ANGLE;const petalW=0.014+t*0.042;const petalH=0.035+t*0.045;let curlAmt,cupAmt,ruffleAmt;if(t<0.15){curlAmt=0.3+t*2;cupAmt=0.06;ruffleAmt=0.0005}else if(t<0.4){curlAmt=0.6+t*1.5;cupAmt=0.04-t*0.04;ruffleAmt=0.001+t*0.003}else if(t<0.7){curlAmt=1+(t-0.4)*2.5;cupAmt=0.015;ruffleAmt=0.002+t*0.004}else{curlAmt=1.6+(t-0.7)*3;cupAmt=0.008;ruffleAmt=0.003+(t-0.7)*0.015}const segs=t<0.2?10:14;const geo=makePetalGeo(petalW,petalH,curlAmt,cupAmt,ruffleAmt,segs);let mat;if(t<0.2)mat=petalCoreMat;else if(t<0.55)mat=petalMidMat;else mat=petalOuterMat;const petal=new THREE.Mesh(geo,mat);const radialDist=t*t*0.035;petal.position.set(Math.cos(angle)*radialDist,-t*0.018,Math.sin(angle)*radialDist);const tiltBack=-0.2-t*1.35;const randomJitter=(Math.random()-0.5)*0.12;petal.rotation.set(tiltBack+randomJitter,angle+Math.PI,randomJitter*0.5);bloom.add(petal)}for(let i=0;i<5;i++){const ang=i/5*Math.PI*2+0.3;const sepalGeo=makePetalGeo(0.014,0.065,2.2+Math.random()*0.5,0.01,0.002,8);const sepal=new THREE.Mesh(sepalGeo,sepalMat);sepal.position.set(Math.cos(ang)*0.012,-0.025,Math.sin(ang)*0.012);sepal.rotation.set(-2.3-Math.random()*0.3,ang,0);bloom.add(sepal)}const calyxGeo=new THREE.SphereGeometry(0.02,14,10,0,Math.PI*2,0,Math.PI*0.55);const calyx=new THREE.Mesh(calyxGeo,sepalMat);calyx.position.set(0,-0.025,0);calyx.rotation.x=Math.PI;bloom.add(calyx);const receptacle=new THREE.Mesh(new THREE.CylinderGeometry(0.006,0.008,0.02,8),sepalMat);receptacle.position.set(0,-0.04,0);bloom.add(receptacle);bloom.rotation.set(Math.PI*0.5,0,0.2);const stemCurve=new THREE.CatmullRomCurve3([new THREE.Vector3,new THREE.Vector3(-0.04,0.002,0.005),new THREE.Vector3(-0.1,0.004,-0.003),new THREE.Vector3(-0.18,0.003,0.008),new THREE.Vector3(-0.26,0.005,-0.002),new THREE.Vector3(-0.34,0.003,0.004),new THREE.Vector3(-0.42,0.004,0)]);const stemGeo=new THREE.TubeGeometry(stemCurve,40,0.0035,8,false);const stem=new THREE.Mesh(stemGeo,stemMat);roseGroup.add(stem);const stemEndPt=stemCurve.getPoint(1);const stemCap=new THREE.Mesh(new THREE.CircleGeometry(0.004,8),new THREE.MeshLambertMaterial({color:197891,emissive:0}));stemCap.position.copy(stemEndPt);stemCap.rotation.set(0,0,Math.PI*0.5);roseGroup.add(stemCap);const thornTs=[0.18,0.32,0.48,0.62,0.78,0.88];thornTs.forEach((t,i)=>{const pt=stemCurve.getPoint(t);const tangent=stemCurve.getTangent(t);const side=i%2===0?1:-1;const thornLen=0.008+Math.random()*0.005;const thornGeo=new THREE.ConeGeometry(0.0015,thornLen,5);const tPos=thornGeo.attributes.position;for(let v=0;v<tPos.count;v++){const y=tPos.getY(v);const hookT=(y+thornLen*0.5)/thornLen;tPos.setZ(v,tPos.getZ(v)+hookT*hookT*0.003*side)}thornGeo.computeVertexNormals();const thorn=new THREE.Mesh(thornGeo,thornMat);thorn.position.copy(pt);thorn.position.y+=0.003*side;thorn.rotation.set(Math.random()*0.3,Math.atan2(tangent.z,tangent.x)+Math.PI*0.5,side*1.1+Math.random()*0.2);roseGroup.add(thorn)});function makeLeafGeo(lw,lh){const segsU=8,segsV=10;const verts=[],uvArr=[],idx=[];for(let iv=0;iv<=segsV;iv++){const v=iv/segsV;const wProfile=Math.sin(v*Math.PI*0.92)*(v<0.5?v*2:1-(v-0.5)*1.2);const hw=lw*0.5*Math.max(0,wProfile);for(let iu=0;iu<=segsU;iu++){const u=iu/segsU;const uc=(u-0.5)*2;let px=uc*hw;let py=lh*v;let pz=-Math.abs(uc)*0.004*v;pz-=v*v*0.006;const edgeWave=Math.abs(uc)>0.7?Math.sin(v*18)*0.0008:0;pz+=edgeWave;verts.push(px,py,pz);uvArr.push(u,v)}}for(let iv=0;iv<segsV;iv++){for(let iu=0;iu<segsU;iu++){const a=iv*(segsU+1)+iu,b=a+1,c=a+segsU+1,d=c+1;idx.push(a,c,b,b,c,d)}}const geo=new THREE.BufferGeometry;geo.setAttribute("position",new THREE.Float32BufferAttribute(verts,3));geo.setAttribute("uv",new THREE.Float32BufferAttribute(uvArr,2));geo.setIndex(idx);geo.computeVertexNormals();return geo}const leafClusters=[{t:0.25,count:5,scale:0.9,rotY:0.8},{t:0.55,count:3,scale:1.1,rotY:-0.5},{t:0.75,count:3,scale:0.8,rotY:1.6}];leafClusters.forEach((cl)=>{const basePt=stemCurve.getPoint(cl.t);const tangent=stemCurve.getTangent(cl.t);const petioleCurve=new THREE.CatmullRomCurve3([basePt.clone(),basePt.clone().add(new THREE.Vector3(0,0.015,0.01*(cl.rotY>0?1:-1)))]);const petioleGeo=new THREE.TubeGeometry(petioleCurve,6,0.0015,4,false);roseGroup.add(new THREE.Mesh(petioleGeo,stemMat));const leafBasePt=petioleCurve.getPoint(1);for(let li=0;li<cl.count;li++){const lGeo=makeLeafGeo(0.018*cl.scale,0.04*cl.scale);const leaf=new THREE.Mesh(lGeo,leafMat);leaf.position.copy(leafBasePt);const spread=(li/(cl.count-1||1)-0.5)*1.4;leaf.rotation.set(-0.6+Math.random()*0.2,cl.rotY+spread+Math.random()*0.2,-0.3*spread);leaf.scale.setScalar(0.7+Math.random()*0.4);roseGroup.add(leaf)}});const bloomAttach=stemCurve.getPoint(0);bloom.position.copy(bloomAttach);roseGroup.add(bloom);function makeFallenPetalGeo(w,h){const segsU=8,segsV=8;const verts=[],uvArr=[],idx=[];for(let iv=0;iv<=segsV;iv++){const v=iv/segsV;const wProfile=Math.sin(v*Math.PI*0.85);const hw=w*0.5*wProfile;for(let iu=0;iu<=segsU;iu++){const u=iu/segsU;const uc=(u-0.5)*2;let px=uc*hw;let py=0;let pz=h*v;const edgeLift=Math.pow(Math.abs(uc),3)*0.006;const tipLift=v>0.7?(v-0.7)*0.015:0;py=edgeLift+tipLift+Math.random()*0.0003;py+=Math.sin(uc*3+v*2)*0.001;verts.push(px,py,pz);uvArr.push(u,v)}}for(let iv=0;iv<segsV;iv++){for(let iu=0;iu<segsU;iu++){const a=iv*(segsU+1)+iu,b=a+1,c=a+segsU+1,d=c+1;idx.push(a,c,b,b,c,d)}}const geo=new THREE.BufferGeometry;geo.setAttribute("position",new THREE.Float32BufferAttribute(verts,3));geo.setAttribute("uv",new THREE.Float32BufferAttribute(uvArr,2));geo.setIndex(idx);geo.computeVertexNormals();return geo}const petals=[{x:0.1,z:0.05,r:0.8,s:1},{x:-0.06,z:0.08,r:2.4,s:0.85},{x:0.15,z:-0.04,r:4.1,s:0.92},{x:-0.12,z:-0.03,r:1.1,s:1.08},{x:0.04,z:0.12,r:5.5,s:0.72},{x:-0.18,z:0.04,r:3.3,s:0.95},{x:0.2,z:0.02,r:0.3,s:0.78},{x:-0.03,z:-0.1,r:2.8,s:1.05},{x:0.08,z:-0.09,r:5,s:0.68},{x:-0.15,z:0.09,r:1.7,s:0.88},{x:0.22,z:-0.07,r:3.9,s:0.82},{x:-0.08,z:-0.13,r:4.6,s:0.75},{x:0.13,z:0.11,r:0.1,s:1.12},{x:-0.22,z:-0.01,r:2,s:0.9},{x:0.02,z:-0.15,r:5.8,s:0.65},{x:-0.25,z:0.06,r:3.6,s:0.8},{x:0.25,z:0.08,r:1.4,s:0.7},{x:-0.05,z:0.16,r:4.3,s:0.92}];petals.forEach((p)=>{const pw=0.028+Math.random()*0.016;const ph=0.04+Math.random()*0.02;const geo=makeFallenPetalGeo(pw,ph);const mat=Math.random()>0.5?fallenMat1:fallenMat2;const petal=new THREE.Mesh(geo,mat);petal.position.set(p.x,0.001,p.z);petal.rotation.set(0,p.r,(Math.random()-0.5)*0.1);petal.scale.setScalar(p.s);roseGroup.add(petal)});for(let i=0;i<10;i++){const fw=0.006+Math.random()*0.008;const fh=0.008+Math.random()*0.012;const fragGeo=makeFallenPetalGeo(fw,fh);const frag=new THREE.Mesh(fragGeo,Math.random()>0.5?fallenMat1:fallenMat2);const ang=Math.random()*Math.PI*2;const dist=0.06+Math.random()*0.28;frag.position.set(Math.cos(ang)*dist,0.0005,Math.sin(ang)*dist);frag.rotation.set(0,Math.random()*Math.PI*2,0);frag.scale.setScalar(0.5+Math.random()*0.6);roseGroup.add(frag)}roseGroup.position.set(0.15,0.02,-1.72);roseGroup.rotation.set(0,0.6,0);return roseGroup}const blackRose3D=buildBlackRose();scene.add(blackRose3D);